const ai = $json.output ?? {};

const rag =
  $('Build RAG Context').first().json ?? {};

const retrievalEvidence =
  Array.isArray(rag.retrievalEvidence)
    ? rag.retrievalEvidence
    : [];

const primaryEvidence =
  retrievalEvidence[0] ?? {};

const retrievalCount =
  Number.isFinite(Number(rag.retrievalCount))
    ? Number(rag.retrievalCount)
    : retrievalEvidence.length;

const retrievalTopScore =
  typeof primaryEvidence.score === 'number' &&
  Number.isFinite(primaryEvidence.score)
    ? primaryEvidence.score
    : null;

const ragGrounded =
  retrievalCount > 0 &&
  typeof rag.sopContext === 'string' &&
  rag.sopContext.trim().length > 0;

const sopSource =
  typeof primaryEvidence.source === 'string'
    ? primaryEvidence.source
    : null;

const sopVersion =
  typeof primaryEvidence.version === 'string'
    ? primaryEvidence.version
    : null;

// ---------- AI业务字段 ----------

const category =
  String(ai.category ?? 'Other');

const priority =
  String(ai.priority ?? 'Normal');

const normalizedCategory = category
  .trim()
  .toLowerCase()
  .replace(/[\s-]+/g, '_');

const bookingCategories = new Set([
  'servicebooking',
  'service_booking',
  'service_reservation',
  'reservation',
  'reservations',
  'booking',
  'bookings'
]);

const requiresBookingWorkflow =
  ai.requiresBookingWorkflow === true ||
  bookingCategories.has(normalizedCategory);

const operationalRequestText =
  String(ai.operationalRequestText ?? '').trim();

const bookingRequestText =
  String(ai.bookingRequestText ?? '').trim();

const hasOperationalRequest =
  ai.hasOperationalRequest === true ||
  operationalRequestText.length > 0 ||
  !requiresBookingWorkflow;

const requiresApproval =
  ai.requiresApproval === true;

const needsHumanEscalation =
  ai.needsHumanEscalation === true;

// 纯预约消息不由本节点生成运营回复
const rawSuggestedReply =
  String(ai.suggestedReply ?? '').trim();

const suggestedReply = hasOperationalRequest
  ? (
      rawSuggestedReply ||
      '已收到该事项，请由值班人员进一步确认。'
    )
  : '';

// ---------- 确定性安全路由 ----------

let route = 'routine';
let finalReply = suggestedReply;

if (
  hasOperationalRequest &&
  needsHumanEscalation
) {
  route = 'human_escalation';

  finalReply =
    `⚠️ 需要立即人工升级\n` +
    `${suggestedReply}\n` +
    `请立即联系值班经理或相关应急负责人。`;
} else if (
  hasOperationalRequest &&
  requiresApproval
) {
  route = 'manager_approval';

  finalReply =
    `⏳ 需要主管审批\n` +
    `${suggestedReply}\n` +
    `在获得批准前，请勿承诺退款、赔偿或特殊安排。`;
}

// ---------- 最终输出 ----------

return [
  {
    json: {
      ...ai,

      category,
      priority,

      requiresApproval,
      needsHumanEscalation,

      requiresBookingWorkflow,
      hasOperationalRequest,
      operationalRequestText,
      bookingRequestText,

      suggestedReply,
      route,
      finalReply,

      ragGrounded,
      sopSource,
      sopVersion,
      retrievalCount,
      retrievalTopScore
    }
  }
];

// 读取 Workflow 02 触发节点收到的原始业务请求
const request = $('When Executed by Another Workflow').first().json;

// 读取 Supabase Vector Store 返回的全部检索结果
const retrievedDocuments = $input
  .all()
  .map((item, index) => {
    const document = item.json.document ?? {};
    const metadata = document.metadata ?? {};

    return {
      rank: index + 1,
      content: document.pageContent ?? '',
      score: item.json.score ?? null,
      source: metadata.source ?? null,
      version: metadata.version ?? null,
      documentType: metadata.document_type ?? null,
    };
  })
  // 防止空文档进入提示词
  .filter((document) => document.content.trim() !== '');

// 将多条 SOP 片段整理成一段可供 LLM 阅读的上下文
const sopContext = retrievedDocuments
  .map((document) => {
    const score =
      typeof document.score === 'number'
        ? document.score.toFixed(3)
        : 'unknown';

    return [
      `[SOP excerpt ${document.rank}]`,
      `Source: ${document.source ?? 'unknown'}`,
      `Version: ${document.version ?? 'unknown'}`,
      `Similarity: ${score}`,
      document.content,
    ].join('\n');
  })
  .join('\n\n');

// 输出一条数据，供后面的 LLM 节点使用
return [
  {
    json: {
      ...request,
      sopContext,
      retrievalCount: retrievedDocuments.length,

      // 只保留审计所需的信息，不重复保存完整正文
      retrievalEvidence: retrievedDocuments.map((document) => ({
        rank: document.rank,
        score: document.score,
        source: document.source,
        version: document.version,
        documentType: document.documentType,
      })),
    },
  },
];
